Ltac lres_copy_tac FRB LVB DDAN LVP PD :=
  unfold lres; repeat match goal with H : rt_frames _ _ = _ |- _ => rewrite H end; repeat match goal with H : rt_live _ _ = _ |- _ => rewrite H end;
  unfold pix_copy_live, pm_copy_live; unfold FRAMES_MAX, LIVE_MAX, RASTER_COST, RC1 in *;
  split; [clear - FRB; lia|];
  split; [destruct (p_cmap _ =? 0); cbn [length app]; clear - LVB; lia|];
  split; [repeat match goal with H : context [rt_credit] |- _ => revert H end; clear; intros; lia|];
  let p := fresh "p" in let n := fresh "n" in let Hn := fresh "Hn" in
  intros p n Hn; apply in_app_or in Hn; destruct Hn as [Hn|Hn];
  [ lazymatch type of PD with pix_obj _ _ _ ?vd _ =>
      destruct (Z.eqb_spec (p_cmap vd) 0) as [CZ|CNZ]; [destruct Hn|];
      let CO := fresh "CO" in let CAN := fresh "CAN" in
      destruct PD as (_ & _ & _ & _ & [CZ'|(CO & _)]); [exfalso; exact (CNZ CZ')|];
      destruct CO as (_ & (_ & _ & _ & _) & (_ & _ & _ & CAN) & _ & _);
      cbn [In] in Hn; destruct Hn as [Hn|[Hn|[]]]; injection Hn as <- <-; [exact CAN| clear; lia] end
  | cbn [In] in Hn; destruct Hn as [Hn|[Hn|Hn]];
    [ injection Hn as <- <-; first [exact DDAN | unfold rsize in *; clear - DDAN; lia]
    | injection Hn as <- <-; clear; lia
    | exact (LVP _ _ Hn) ] ].

